const appealsSection=document.createElement('section');appealsSection.className='official-appeals';appealsSection.innerHTML='<div class="section-heading"><div><span class="eyebrow">OFFICIAL REQUESTS FOR PUBLIC HELP</span><h2>Real cases. Evidence needed.</h2></div><span class="appeals-checked">Sources checked<br><b>02 OCT 2026</b></span></div><div class="appeals-grid">'+officialAppeals.map(a=>'<article class="appeal-card"><figure class="appeal-visual"><img src="assets/appeals/context-'+(['psni','hampshire','jeffco','tuscaloosa'][officialAppeals.indexOf(a)])+'.svg" alt="Location context for '+escapeHtml(a.place)+'"><figcaption>Location context · not incident footage</figcaption></figure><span class="appeal-agency">'+a.agency+'</span><span class="appeal-place">'+a.place+'</span><h3>'+a.title+'</h3><p>'+a.summary+'</p><div class="appeal-date">'+a.date+'</div><div class="appeal-ref">'+a.reference+'</div><a href="'+a.url+'" target="_blank" rel="noopener">Read official appeal ↗</a></article>').join('')+'</div><p class="appeals-note">These are public agency appeals, not Parallax investigations. Check the linked source for updates and submit relevant information directly to the agency. No camera evidence has been collected or analyzed for these cases.</p>';
document.querySelector('.stats').before(appealsSection);
